# owner: platform

import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span


def shift(worker: str, start: int, end: int) -> Shift:
    return Shift(worker, "mon", Span(start, end))


class TimesheetTests(unittest.TestCase):
    def test_busiest_workers_first(self):
        shifts = [
            shift("Odell", 750, 900),
            shift("Brisa", 540, 780),
            shift("Quill", 660, 990),
            shift("Brisa", 840, 1020)
        ]
        self.assertEqual(
            timesheet_rows(shifts), ["Brisa, 2, 7.0", "Quill, 1, 5.5", "Odell, 1, 2.5"]
        )

    def test_hours_rounded_to_one_decimal(self):
        self.assertEqual(timesheet_rows([shift("Odell", 540, 640)]), ["Odell, 1, 1.7"])

    def test_ties_sorted_by_name(self):
        shifts = [shift("Quill", 540, 600), shift("Brisa", 600, 660)]
        self.assertEqual(
            timesheet_rows(shifts), ["Brisa, 1, 1.0", "Quill, 1, 1.0"]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_rows([shift("  ", 540, 600)])
